const output = $input.first().json.output;
const jsonMatch = output.match(/\{[\s\S]*\}/);
if (!jsonMatch) throw new Error('No JSON found in output');
const parsed = JSON.parse(jsonMatch[0]);
return [{ json: parsed }];

function extractText(parts) {
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) {
      return Buffer.from(part.body.data, 'base64').toString('utf-8');
    }
    if (part.parts) {
      const result = extractText(part.parts);
      if (result) return result;
    }
  }
  return null;
}

const messageId = $input.first().json.id;
const payload = $input.first().json.payload;
const parts = payload?.parts || [];

let mailText = extractText(parts);
if (!mailText) {
  mailText = $input.first().json.snippet || '';
}

const attachmentParts = parts.filter(p => p.filename && p.filename.length > 0 && p.body?.attachmentId);
const hasAttachment = attachmentParts.length > 0;
const attachmentId = hasAttachment ? attachmentParts[0].body.attachmentId : null;
const filename = hasAttachment ? attachmentParts[0].filename : null;

return [{
  json: {
    messageId,
    mailText,
    hasAttachment,
    attachmentId,
    filename
  }
}];

